import json

raw = (request.get("body") or "").strip()
if not raw:
    return {}
try:
    parsed = json.loads(raw)
except ValueError:
    raise ValueError("request body is not valid JSON")
if not isinstance(parsed, dict):
    raise ValueError("request body must be a JSON object")
return parsed

import urllib.parse

parsed = urllib.parse.parse_qs(request.get("query", ""), keep_blank_values=False)
return {key: values[0] for key, values in parsed.items() if values}

try:
    limit = int(query.get("limit", default_limit))
except (TypeError, ValueError):
    limit = default_limit
try:
    offset = int(query.get("offset", 0))
except (TypeError, ValueError):
    offset = 0
return {"limit": max(1, min(limit, 500)), "offset": max(0, min(offset, 100000))}

import hashlib

headers = request.get("headers") or {}
material = headers.get("user-agent", "") + "|" + request.get("address_family", "")
return hashlib.sha256(material.encode("utf-8")).hexdigest()
